'use strict';
const VERSION='1.10.0', KEY='greenforce-manager-pro-v1:'+new URL('./',location.href).pathname, TABLES=['clients','subscriptions','visits','payments','expenses','documents','supplies','purchases','equipment','irrigation','services','recommendations','portfolio','irrigationLogs',...MANAGER_TABLES];
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), cents=v=>Math.round((Number(v)||0)*100), money=v=>new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'}).format(v||0), sum=(arr,fn)=>arr.reduce((a,r)=>a+cents(fn(r)),0)/100;
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2), date=v=>v?new Date(v+'T12:00:00').toLocaleDateString('bg-BG'):'—';
const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M4 5h16v16H4zM16 3v4M8 3v4M4 10h16M8 14h1M12 14h1M16 14h1M8 18h1M12 18h1',visit:'M9 3h6v4H9zM8 5H5v17h14V5h-3M8 14l3 3 5-6',doc:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',contract:'M3 8l4-3 5 2 5-2 4 3-4 9-4 3-9-6zM7 8l5 5 4-4M7 16l3 3',chart:'M4 21V11h3v10M11 21V7h3v14M18 21V3h3v18M3 5l6-2 5 1 6-3',cart:'M2 3h3l3 12h11l3-9H6M10 21h.01M18 21h.01',box:'M3 7l9-5 9 5v11l-9 5-9-5zM3 7l9 5 9-5M12 12v11M7 4l10 6',water:'M12 2C9 7 4 11 4 15a8 8 0 0 0 16 0c0-4-5-8-8-13zM8 15a4 4 0 0 0 4 4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',back:'M15 4l-8 8 8 8',plus:'M12 4v16M4 12h16',chevron:'M9 5l7 7-7 7',money:'M3 5h18v14H3zM7 9h.01M17 15h.01M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4',tool:'M14 6a5 5 0 0 0-6 6l-6 6 4 4 6-6a5 5 0 0 0 6-6l-4 3-3-3z',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',check:'M4 12l5 5L20 6',edit:'M15 3l6 6-12 12H3v-6zM12 6l6 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l4 2',leaf:'M5 20C3 8 10 3 21 3c0 12-5 18-16 17zM5 20l10-10',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',close:'M5 5l14 14M5 19 19 5'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.leaf}"/></svg>`;
function visitHours(v){return Number.isFinite(v.durationHours)?v.durationHours:(Number(v.duration)||0)/60}
function isAllocation(r){return r.flowType==='Разпределение на остатъка'}
function allocationCategories(){return Object.keys(db.settings.allocation)}
function net(v){return Math.round(cents(v.amount)*(1-Number(v.discount||0)/100))/100}
function blank(){return {schemaVersion:1,...Object.fromEntries(TABLES.map(k=>[k,[]])),settings:{company:'GreenForce Озеленяване',owner:'',phone:'',email:'',address:'',registration:'',allocation:{'Лични средства':20,'Семейство':30,'Гориво':20,'Инвестиции':20,'Данъчен резерв':10},logo:''}}}
let db=blank(),storageError='',corrupt=false;
function loadSavedData(){try{const raw=localStorage.getItem(KEY);if(raw){db=validate(JSON.parse(raw))}}catch(e){storageError='Запазените данни не могат да се прочетат. Изтегли ги от Настройки, преди да изчистиш хранилището.';corrupt=true}}
let state={page:'home',month:today().slice(0,7),day:today(),client:null,tab:'',filter:'',supplyClient:'',docType:'Оферта',reportBasis:'visit'};
function save(){if(corrupt)throw Error('Хранилището е блокирано за защита на нечетимите данни. Виж Настройки.');localStorage.setItem(KEY,JSON.stringify(db))}
function change(fn){const old=JSON.stringify(db);try{fn();managerValidate(db);db.settings.mutationCounter=(db.settings.mutationCounter||0)+1;save();navRevision++;return true}catch(e){db=JSON.parse(old);toast('Данните не са записани: '+e.message);return false}}
function validate(v){if(v&&v.schemaVersion===1)for(const k of [...MANAGER_TABLES,'recommendations','portfolio','irrigationLogs'])if(!(k in v))v[k]=[];if(!v||v.schemaVersion!==1||!v.settings||!TABLES.every(k=>Array.isArray(v[k])))throw Error('Невалиден формат на архив');let ids=new Set;for(const k of TABLES){if(v[k].length>50000)throw Error('Архивът е твърде голям');for(const r of v[k]){if(!r||typeof r!=='object'||typeof r.id!=='string'||ids.has(r.id))throw Error('Невалиден или повторен идентификатор');ids.add(r.id);for(const [f,x]of Object.entries(r)){if(typeof x==='number'&&(!Number.isFinite(x)||Math.abs(x)>1e10))throw Error('Невалидна стойност');if(typeof x==='string'&&x.length>2500000)throw Error('Твърде дълъг запис')}if(r.date&&!/^\d{4}-\d{2}-\d{2}$/.test(r.date))throw Error('Невалидна дата')}}
 const required={payments:['visitId','date','method'],clients:['name'],subscriptions:['name','clientId','start','end','service'],visits:['clientId','date','time','service'],expenses:['description','date','category'],documents:['type','number','title','clientId','date','validUntil','items'],supplies:['clientId','name','unit'],purchases:['name','unit','date'],equipment:['name'],irrigation:['name','clientId'],services:['name','unit']};
 for(const k of TABLES)for(const r of v[k]){for(const field of (required[k]||[]))if(typeof r[field]!=='string'||!r[field].trim())throw Error('Липсва задължително поле в '+k);for(const field of ['date','start','end','validUntil','nextService','winterized','periodStart','periodEnd'])if(r[field]&&(typeof r[field]!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r[field])||!Number.isFinite(+new Date(r[field]+'T12:00:00'))))throw Error('Невалидна дата');if(r.coverPhoto&&!/^data:image\/(jpeg|png|webp);base64,/.test(r.coverPhoto))throw Error('Невалидна снимка на корица');if(r.photo&&!/^data:image\/(jpeg|png|webp);base64,/.test(r.photo))throw Error('Невалидна снимка');}
 for(const r of v.subscriptions)if(!Number.isInteger(r.frequency)||r.frequency<1||r.frequency>31||r.end<r.start)throw Error('Невалиден абонамент');
 for(const r of v.documents)if(!['Оферта','Договор'].includes(r.type)||!Number.isFinite(r.discount)||r.discount<0||r.discount>100||r.validUntil<r.date||docLines(r).some(l=>!Number.isFinite(l.qty)||!Number.isFinite(l.price)||l.qty<=0||l.price<0))throw Error('Невалиден документ');
 if(typeof v.settings.company!=='string'||(v.settings.logo&&!/^data:image\/(jpeg|png|webp);base64,/.test(v.settings.logo)))throw Error('Невалидни настройки');
 const clientIds=new Set(v.clients.map(r=>r.id)),visitIds=new Set(v.visits.map(r=>r.id));for(const k of TABLES)for(const r of v[k])if(r.clientId&&!clientIds.has(r.clientId))throw Error('Липсва клиент за запис');for(const p of v.payments)if(!visitIds.has(p.visitId)||!(p.amount>0))throw Error('Невалидно плащане');
 for(const k of ['visits','expenses','purchases','subscriptions','services'])for(const r of v[k])if('amount'in r&&(!Number.isFinite(r.amount)||r.amount<0))throw Error('Невалидна сума');
 for(const v1 of v.visits){if(!['Планирано','Изпълнено','Отменено'].includes(v1.status)||!Number.isFinite(v1.discount)||v1.discount<0||v1.discount>100)throw Error('Невалидно посещение');if(sum(v.payments.filter(p=>p.visitId===v1.id),p=>p.amount)>net(v1)+.005)throw Error('Надплатено посещение')}
 for(const r of mediaRecords(v))for(const g of ['beforePhotos','afterPhotos','documentPhotos','receiptPhotos','irrigationPhotos'])if(r[g]&&(!Array.isArray(r[g])||r[g].length>photoLimit(g)||r[g].some(id=>typeof id!=='string'||!id||id.length>100)))throw Error('Невалидна група със снимки');for(const r of v.visits)if(r.durationHours!=null&&(!Number.isFinite(r.durationHours)||r.durationHours<0||r.durationHours>168))throw Error('Невалидна продължителност');for(const r of v.expenses)if(r.flowType&&!['Разход за дейността','Разпределение на остатъка'].includes(r.flowType))throw Error('Невалидно разпределение');
 for(const r of v.documents)if(r.template&&r.template!=='Свободен документ'&&(!GFTemplates.names.includes(r.template)||!r.periodStart||!r.periodEnd||r.periodEnd<r.periodStart||!Number.isInteger(r.visitsPerMonth)||r.visitsPerMonth<1||r.visitsPerMonth>31))throw Error('Невалиден шаблон на документ');
 validateIrrigation(v);validatePortfolio(v);validateRecommendations(v);for(const r of v.documents){validateDocumentPricing(r);validateDocumentExtras(r);}validateFeatures(v);managerValidate(v);const alloc=v.settings.allocation;if(!alloc||Object.values(alloc).some(x=>typeof x!=='number'||x<0||x>100)||Math.abs(Object.values(alloc).reduce((a,b)=>a+b,0)-100)>.001)throw Error('Разпределението трябва да е 100%');return v;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4800)}
const client=id=>db.clients.find(r=>r.id===id), cname=id=>client(id)?.name||'Общо за фирмата', inMonth=r=>r.date?.startsWith(state.month), paid=v=>directPaid(v)+monthlyCredit(v), due=v=>Math.max(0,(cents(net(v))-cents(paid(v)))/100);
const btn=(text,action,ic='plus',cls='primary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${icon(ic)}${esc(text)}</button>`;
const empty=(s='Няма въведени записи.')=>`<div class="empty">${icon('leaf')}${esc(s)}</div>`;
const badge=(s,cls='')=>`<span class="badge ${cls}">${esc(s)}</span>`;
const tabs=(names,active)=>`<div class="tabs">${names.map(n=>`<button data-action="tab" data-value="${esc(n)}" class="${n===active?'active':''}">${esc(n)}</button>`).join('')}</div>`;
function period(){return `<div class="period"><button class="iconbtn" data-action="month" data-dir="-1" aria-label="Предишен месец">${icon('back')}</button><label for="month">Период</label><div class="month-picker"><span>${esc(new Date(state.month+'-01T12:00:00').toLocaleDateString('bg-BG',{month:'long',year:'numeric'}))} ${icon('calendar')}</span><input id="month" type="month" value="${state.month}" aria-label="Месец"></div><button class="iconbtn" data-action="month" data-dir="1" aria-label="Следващ месец">${icon('chevron')}</button></div>`}
function paymentDate(p,basis='payment'){if(p.kind==='subscription')return basis==='visit'?p.month+'-01':p.date;return basis==='visit'?(db.visits.find(v=>v.id===p.visitId)?.date||p.date):p.date}
function reportBasis(){return state.page==='reports'?state.reportBasis:'payment'}
function paymentInMonth(p){return paymentDate(p,reportBasis()).startsWith(state.month)}
function stats(month=state.month,basis=reportBasis()){return {allocated:sum(db.expenses.filter(p=>p.date.startsWith(month)&&isAllocation(p)),p=>p.amount),income:sum(cashEntries().filter(p=>paymentDate(p,basis).startsWith(month)),p=>p.amount),expense:sum(db.expenses.filter(p=>p.date.startsWith(month)&&!isAllocation(p)),p=>p.amount)}}
function kpis(){let s=stats();return `<div class="kpis"><div class="kpi lime"><small>Получени приходи</small><strong>${money(s.income)}</strong><small>${cashEntries().filter(paymentInMonth).length} плащания</small></div><div class="kpi blue"><small>Разходи</small><strong>${money(s.expense)}</strong><small>${db.expenses.filter(r=>inMonth(r)&&!isAllocation(r)).length} записа</small></div><div class="kpi green"><small>${reportBasis()==='visit'?'Резултат по посещения':'Паричен резултат'}</small><strong>${money(s.income-s.expense)}</strong><small>Приходи минус разходи</small></div></div>`}
const menu=[['clients','Клиенти','users'],['calendar','Календар','calendar'],['visits','Посещения','visit'],['documents','Оферти','doc'],['contracts','Договори','contract'],['reports','Справки','chart'],['purchases','Пазаруване','cart'],['supplies','Консумативи','box'],['subscriptions','Абонаменти','calendar'],['finance','Финанси','money'],['equipment','Оборудване','tool'],['irrigation','Поливни системи','water']];
const titles={home:'GreenForce Manager Pro',client:'Досие на клиент',settings:'Настройки',notifications:'Предстоящи задачи',services:'Ценоразпис услуги',...Object.fromEntries(menu.map(m=>[m[0],m[1]]))};
function go(page,options={}){navPush();state={...state,page,tab:'',filter:'',...options};render();window.scrollTo(0,0)}
function render(){const home=state.page==='home';$('#app').innerHTML=`<div class="app-shell"><header>${home?`<div class="brand"><img src="${esc(db.settings.logo||'./assets/greenforce-icon-192-v112.png')}" alt=""><div><strong>Green<span>Force</span></strong><br><small>MANAGER PRO</small></div></div>`:`<div class="row"><button class="iconbtn" data-action="back" aria-label="Назад">${icon('back')}</button><h1>${esc(titles[state.page]||'GreenForce')}</h1></div>`}<button class="iconbtn" data-action="go" data-page="settings" aria-label="Настройки">${icon('settings')}</button></header><main>${storageError?`<div class="error">${esc(storageError)}</div>`:''}${views[state.page]?.()||empty()}<div class="statusline"><span>${navigator.onLine?'● Онлайн':'● Офлайн'} · v${VERSION}</span><span id="offline-status">${swReady?'Готово за офлайн':'Подготовка за офлайн…'}</span></div></main><nav>${[['home','Начало','home'],['calendar','Календар','calendar'],['reports','Справки','chart'],['notifications','Задачи','bell'],['settings','Профил','users']].map(([p,t,i])=>`<button data-action="go" data-page="${p}" class="${state.page===p?'active':''}">${icon(i)}${t}</button>`).join('')}</nav></div>`;if(state.page==='reports')drawChart();hydratePhotos($('#app'));}
function homeView(){const upcoming=db.visits.filter(v=>v.date>=today()&&v.status==='Планирано').sort(sortDate).slice(0,3);return `<div class="hero"><div class="eyebrow">Твоят бизнес. Под контрол.</div><h2>Максимум <span>зеленина.</span><br>Минимум усилия.</h2><p>Професионална грижа за всяка градина.</p></div>${period()}<div class="home-layout"><div class="dashboard-grid">${menu.slice(0,8).map(([p,t,i])=>btn(t,'go',i,'tile',`data-page="${p}"`)).join('')}</div>${kpis()}</div><div class="card tint row between"><div>${icon('users')} <strong>${db.clients.length} клиенти</strong><br><small>Неплатени изпълнени посещения: ${money(sum(db.visits.filter(v=>v.status==='Изпълнено'),due))}</small></div>${btn('Клиенти','go','chevron','iconbtn','data-page="clients"')}</div><div class="card"><div class="card-title"><h3>Предстоящи посещения</h3>${btn('Ново','new','plus','secondary','data-table="visits"')}</div>${upcoming.length?upcoming.map(visitRow).join(''):empty('Няма планирани посещения.')}</div><div class="dashboard-grid">${menu.slice(8).map(([p,t,i])=>btn(t,'go',i,'tile',`data-page="${p}"`)).join('')}</div>${btn('Ценоразпис услуги','go','doc','secondary wide','data-page="services"')}<p class="slogan">GreenForce — Заедно към по-зелена София.</p>${!db.clients.length?`<div class="notice">Започни с нов клиент или зареди примерни записи, за да разгледаш всички модули.${btn('Примерни данни','demo','leaf','secondary wide')}</div>`:''}`}
function clientsView(){return `<input class="search" id="client-search" placeholder="Търси клиент, телефон или адрес…" value="${esc(state.filter)}" aria-label="Търси клиент"><div class="card" id="client-list">${clientList()}</div>${btn('Нов клиент / обект','new','plus','primary wide','data-table="clients"')}`}
function clientList(){return db.clients.filter(c=>[c.name,c.address,c.phone].join(' ').toLocaleLowerCase('bg').includes(state.filter.toLocaleLowerCase('bg'))).map(c=>`<button class="list-row" data-action="client" data-id="${esc(c.id)}"><div class="avatar">${c.photo?`<img src="${esc(c.photo)}" alt="">`:icon('home')}</div><div class="grow"><strong>${esc(c.name)}</strong><small>${esc(c.type||'Обект')} ${c.area?'· '+esc(c.area)+' m²':''}</small><small>${esc(c.address)}</small><small>Разходи общо: <strong>${money(sum(clientExpenses(c.id),e=>e.amount))}</strong></small></div>${icon('chevron')}</button>`).join('')||empty('Няма намерени клиенти.')}
const sortDate=(a,b)=>(a.date+'T'+(a.time||'')).localeCompare(b.date+'T'+(b.time||''));
function visitRow(v){return `<button class="list-row" data-action="edit" data-table="visits" data-id="${esc(v.id)}"><div class="avatar">${icon('visit')}</div><div class="grow"><strong>${esc(cname(v.clientId))}</strong><small>${date(v.date)} · ${esc(v.time)} · ${esc(v.service)}</small><small>${esc(v.status)} · ${visitHours(v).toLocaleString('bg-BG')} ч. · ${(v.beforePhotos?.length||0)+(v.afterPhotos?.length||0)} снимки · ${due(v)>0?'Остатък '+money(due(v)):'Платено'}</small></div><strong>${money(net(v))}</strong></button>`}
function clientView(){const c=client(state.client);if(!c)return empty('Клиентът не е намерен.');let vs=db.visits.filter(v=>v.clientId===c.id).sort(sortDate).reverse(), tab=state.tab||'История';return `<div class="card"><div class="row"><div class="avatar photo-large">${c.photo?`<img src="${esc(c.photo)}" alt="">`:icon('home')}</div><div class="grow"><h2>${esc(c.name)}</h2><p>${esc(c.type)} · ${esc(c.area||'—')} m²<br>${esc(c.address)}<br>${c.phone?`<a href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">${esc(c.phone)}</a>`:''}</p></div>${btn('','edit','edit','iconbtn',`data-table="clients" data-id="${esc(c.id)}" aria-label="Редактирай клиент"`)}</div>${c.notes?`<p class="muted">${esc(c.notes)}</p>`:''}${clientObjectGallery(c)}</div>${clientVisitCounter(c.id)}${tabs(['История','Разходи','Консумативи','Поливни системи'],tab)}${btn('Досие PDF с разходи','clientpdf','download','secondary wide',`data-id="${c.id}"`)}${tab==='История'?`<div class="card table-scroll"><table class="client-history"><thead><tr><th>Дата / услуга</th><th>Сума</th><th>Платено</th><th>Разходи</th></tr></thead><tbody>${vs.map(v=>`<tr><td><button class="iconbtn" data-action="edit" data-table="visits" data-id="${v.id}">${date(v.date)}<br>${esc(v.service)}</button></td><td class="money">${money(net(v))}</td><td class="money">${money(paid(v))}</td><td class="money">${money(sum(visitExpenses(v.id),e=>e.amount))}</td></tr>`).join('')}</tbody></table>${vs.length?'':empty()}</div><div class="total">Общо получени приходи от клиента<strong>${money(sum(cashEntries().filter(p=>cashClient(p)===c.id),p=>p.amount))}</strong></div><div class="total">Общо разходи за обекта<strong>${money(sum(clientExpenses(c.id),e=>e.amount))}</strong></div><small>Колоната „Разходи“ включва само изрично свързаните посещения. В раздел „Разходи“ са и останалите разходи за обекта.</small>${btn('Добави посещение','new','plus','primary wide',`data-table="visits" data-client="${c.id}"`)}<div class="actions">${btn('Досие PDF','clientpdf','download','secondary',`data-id="${c.id}"`)}${btn('Поливна система','new','water','secondary',`data-table="irrigation" data-client="${c.id}"`)}</div>`:tab==='Разходи'?clientExpenseView(c.id):tab==='Консумативи'?supplyContent(c.id):`<div class="card">${clientIrrigationHTML(c.id)||empty('Няма технически записи.')}${btn('Нов проект / система','new','plus','primary wide',`data-table="irrigation" data-client="${c.id}"`)}</div>`}`}
function calendarView(){const [year,month]=state.month.split('-').map(Number),count=new Date(year,month,0).getDate(),start=(new Date(year,month-1,1).getDay()+6)%7;return `${period()}<div class="card"><div class="calendar">${['П','В','С','Ч','П','С','Н'].map(t=>`<div class="weekday">${t}</div>`).join('')}${'<div></div>'.repeat(start)}${Array.from({length:count},(_,i)=>{let d=state.month+'-'+String(i+1).padStart(2,'0');return `<button class="day ${d===state.day?'selected':''} ${d===today()?'today':''}" data-action="day" data-date="${d}" aria-label="${date(d)}" aria-pressed="${d===state.day}">${i+1}${db.visits.some(v=>v.date===d&&v.status!=='Отменено')?'<i class="dot"></i>':''}</button>`}).join('')}</div><p class="muted" style="font-size:11px;margin-top:14px">● Планирано или изпълнено посещение</p></div><div class="card"><h3>Задачи за ${date(state.day)}</h3>${db.visits.filter(v=>v.date===state.day).sort(sortDate).map(visitRow).join('')||empty('Няма посещения за този ден.')}</div><div class="actions">${btn('Ново посещение','new','plus','primary','data-table="visits"')}${btn('Календар .ics','ics','download','secondary')}</div>`}
function visitsView(){const list=db.visits.filter(inMonth).filter(v=>!state.filter||v.clientId===state.filter).sort(sortDate);return `${period()}${clientSelect('visit-client',state.filter,true)}<div class="card">${list.map(visitRow).join('')||empty()}</div>${btn('Ново посещение','new','plus','primary wide','data-table="visits"')}`}
function clientSelect(id,value,all=false){return `<select id="${id}" class="search" aria-label="Избор на клиент"><option value="">${all?'Всички клиенти':'Избери клиент'}</option>${db.clients.map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`}
const cats=['Транспорт','Гориво','Оборудване','Консумативи','Данъци','Подизпълнител','Наем на техника','Други'];
function financeView(){const t=state.tab||'Приходи',s=stats(),result=s.income-s.expense;return `${period()}${kpis()}<div class="money-flow"><div><small>Разпределено за месеца</small><strong>${money(s.allocated)}</strong></div><div><small>Остава за разпределяне</small><strong>${money(result-s.allocated)}</strong></div></div>${tabs(['Приходи','Разходи','Разпределение'],t)}${t==='Приходи'?`<div class="card"><h3>Получени плащания</h3>${cashEntries().filter(inMonth).sort(sortDate).reverse().map(p=>{const v=db.visits.find(v=>v.id===p.visitId);return `<div class="list-row"><div class="grow"><strong>${esc(cname(cashClient(p)))}</strong><small>${date(p.date)} · ${esc(p.method)} · ${esc(p.notes)}</small></div><strong>${money(p.amount)}</strong>${p.kind==='subscription'?btn('','edit','edit','iconbtn',`data-table="subscriptionPayments" data-id="${p.id}" aria-label="Редактирай месечно плащане"`):btn('','delpayment','trash','iconbtn',`data-id="${p.id}" aria-label="Изтрий плащане"`)}</div>`}).join('')||empty('Плащане се добавя от посещението.')}</div>`:t==='Разходи'?`<div class="card"><h3>Разходи за дейността</h3>${expenseChart()}${cats.map(c=>`<div class="row between" style="margin:12px 0"><span>${esc(c)}</span><strong>${money(sum(db.expenses.filter(e=>inMonth(e)&&!isAllocation(e)&&e.category===c),e=>e.amount))}</strong></div>`).join('')}</div><div class="card"><h3>Всички движения за месеца</h3>${db.expenses.filter(inMonth).sort(sortDate).reverse().map(r=>recordRow('expenses',r)).join('')||empty()}</div>${btn('Нов разход / разпределение','new','plus','primary wide','data-table="expenses"')}`:`<div class="card"><h3>Реално разпределени средства</h3>${allocationCategories().map(n=>`<div class="row between" style="padding:10px 0"><span>${esc(n)}</span><strong>${money(sum(db.expenses.filter(e=>inMonth(e)&&isAllocation(e)&&e.category===n),e=>e.amount))}</strong></div>`).join('')}${btn('Запиши разпределение','new-allocation','plus','primary wide')}</div><div class="card"><h3>История на разпределението</h3>${db.expenses.filter(e=>inMonth(e)&&isAllocation(e)).sort(sortDate).reverse().map(r=>recordRow('expenses',r)).join('')||empty('Още няма записани разпределения.')}</div><div class="card"><h3>Препоръка по избраните проценти</h3><p class="muted">База: ${money(Math.max(0,result))}. Реалните преводи се въвеждат отделно.</p>${allocationRows(result)}</div>${btn('Промени процентите','allocation','edit','secondary wide')}<div class="notice">Разпределянето намалява свободния остатък. Реално платено гориво, наем или техника се отчита като разход за дейността; заделянето на пари за бъдеща покупка е разпределение.</div>`}`}
function expenseChart(){const values=cats.map(n=>sum(db.expenses.filter(r=>inMonth(r)&&!isAllocation(r)&&r.category===n),r=>r.amount)),total=values.reduce((a,b)=>a+b,0),colors=['#f19b3c','#9ed337','#007236','#35a8bd','#4d6ca4','#a2b4aa'];let position=0;const stops=values.map((v,i)=>{let start=position;position+=total?v/total*100:0;return `${colors[i]} ${start}% ${position}%`});return `<div class="row" style="gap:22px;flex-wrap:wrap"><div class="donut" style="background:conic-gradient(${total?stops.join(','):'#dce7df 0% 100%'})"><div>${money(total)}</div></div><div class="grow">${cats.filter((n,i)=>values[i]>0).map(n=>{const i=cats.indexOf(n);return `<div class="row between" style="font-size:12px;margin:6px 0"><span><i style="display:inline-block;background:${colors[i]};width:9px;height:9px;border-radius:50%;margin-right:5px"></i>${n}</span><strong>${Math.round(values[i]/total*100)}%</strong></div>`}).join('')||'<small>Няма разходи за периода.</small>'}</div></div>`}
function allocationRows(result){const entries=Object.entries(db.settings.allocation);let assigned=0,base=Math.max(0,cents(result));return entries.map(([n,p],i)=>{const value=i===entries.length-1?base-assigned:Math.round(base*p/100);assigned+=value;return `<div class="row between" style="padding:10px 0;border-bottom:1px solid var(--line)"><span>${esc(n)} <small>${p}%</small></span><strong>${money(value/100)}</strong></div>`}).join('')}
function reportsView(){let tab=state.tab||'Финансови',s=stats(),previous=(Number(state.month.slice(0,4))-1)+state.month.slice(4),p=stats(previous),delta=p.income?((s.income/p.income-1)*100).toFixed(1)+'%':'Няма база за сравнение';return `${period()}<label class="field">Отчитане на приходите<select id="report-basis"><option value="visit" ${state.reportBasis==='visit'?'selected':''}>По дата на посещението</option><option value="payment" ${state.reportBasis==='payment'?'selected':''}>По дата на плащането</option></select></label><p class="muted">Показват се само получени суми. ${state.reportBasis==='visit'?'Плащанията се отнасят към месеца на посещението.':'Плащанията се отнасят към месеца на получаването.'} Разходите са по датата на разхода.</p>${tabs(['Финансови','Клиенти','Услуги'],tab)}${tab==='Клиенти'?yearTotalsView():kpis()}${tab==='Финансови'?`<div class="card"><h3>Приходи ${state.month.slice(0,4)} / ${Number(state.month.slice(0,4))-1}</h3><p class="muted">За избрания месец: ${esc(delta)} спрямо миналата година.</p><canvas id="chart" class="chart" aria-label="Месечни приходи за текущата и предишната година" role="img"></canvas><div class="legend"><span><i class="previous"></i>${Number(state.month.slice(0,4))-1}</span><span><i></i>${state.month.slice(0,4)}</span></div></div>${yearTotalsView()}<div class="card annual-breakdown"><h3>Годишна разбивка · ${state.month.slice(0,4)}</h3><div class="annual-table-wrap"><table class="annual-table"><thead><tr><th>Месец</th><th>Приходи</th><th>Разходи</th><th>Резултат</th></tr></thead><tbody>${Array.from({length:12},(_,i)=>{let m=state.month.slice(0,4)+'-'+String(i+1).padStart(2,'0'),s=stats(m);return `<tr><td title="${m}">${['Яну','Фев','Мар','Апр','Май','Юни','Юли','Авг','Сеп','Окт','Ное','Дек'][i]}</td><td class="money">${money(s.income)}</td><td class="money">${money(s.expense)}</td><td class="money">${money(s.income-s.expense)}</td></tr>`}).join('')}</tbody><tfoot><tr><th scope="row" aria-label="Общо за годината">Общо</th><th class="money">${money(annualStats().income)}</th><th class="money">${money(annualStats().expense)}</th><th class="money">${money(annualStats().profit)}</th></tr></tfoot></table></div></div>`:tab==='Клиенти'?annualClientsView():`<div class="card"><h3>Изпълнени услуги (стойност по посещения)</h3>${[...new Set(db.visits.filter(v=>inMonth(v)&&v.status==='Изпълнено').map(v=>v.service))].map(n=>`<div class="list-row"><span class="grow">${esc(n)}</span><strong>${money(sum(db.visits.filter(v=>inMonth(v)&&v.status==='Изпълнено'&&v.service===n),net))}</strong></div>`).join('')||empty()}</div>`}<div class="actions">${btn('Годишен PDF','annualpdf','download','secondary')}${btn('Месечен PDF','reportpdf','download','secondary')}${btn('CSV износ','csv','download','secondary')}</div>`}
function drawChart(){const el=$('#chart');if(!el)return;const w=el.clientWidth||340,h=220,ratio=devicePixelRatio||1;el.width=w*ratio;el.height=h*ratio;const c=el.getContext('2d');c.scale(ratio,ratio);const year=Number(state.month.slice(0,4)),values=[year-1,year].map(y=>Array.from({length:12},(_,i)=>stats(y+'-'+String(i+1).padStart(2,'0')).income)),max=Math.max(1,...values.flat()),left=38,base=185,step=(w-left-8)/12;c.font='9px sans-serif';c.textAlign='right';for(let i=0;i<=4;i++){const y=base-i*38;c.strokeStyle='#e1e9e2';c.beginPath();c.moveTo(left,y);c.lineTo(w,y);c.stroke();c.fillStyle='#6d7a70';c.fillText(Math.round(max*i/4).toString(),left-5,y+3)}values.forEach((vs,j)=>{c.fillStyle=j?'#006b2c':'#bad6a9';vs.forEach((v,i)=>c.fillRect(left+i*step+j*step*.35,base-v/max*152,step*.3,Math.max(1,v/max*152)))});c.textAlign='center';c.fillStyle='#4f6554';['Я','Ф','М','А','М','Ю','Ю','А','С','О','Н','Д'].forEach((n,i)=>c.fillText(n,left+i*step+step*.35,206));}
function docLines(r){return (r.items||'').split('\n').filter(x=>x.trim()).map(l=>{const p=l.split('|').map(x=>x.trim());return {name:p[0],qty:Number(p[1]||1),price:Number((p[2]||'0').replace(',','.'))}})}
const docTotal=r=>Math.round(cents(documentSubtotal(r))*(1-Number(r.discount||0)/100))/100;
function documentsView(){let t=state.page==='contracts'?'Договор':state.tab||'Оферта';return `${state.page==='contracts'?'':tabs(['Оферта','Договор'],t)}<div class="notice">Редактируеми документи с позиции и условия. PDF се създава директно на устройството, включително офлайн.</div>${db.documents.filter(r=>r.type===t).sort(sortDate).reverse().map(r=>`<div class="card"><div class="row"><div class="avatar">${icon(r.type==='Договор'?'contract':'doc')}</div><div class="grow"><strong>${esc(r.type)} #${esc(r.number)}</strong><small class="stack">${esc(cname(r.clientId))}<br>${date(r.date)} · До ${date(r.validUntil)}</small></div>${badge(r.status,r.status==='Изпратена'?'blue':'')}</div><div class="row between" style="margin-top:12px"><span>${esc(r.title)}</span><strong class="item-amount">${money(docTotal(r))}</strong></div><div class="actions">${btn('Преглед','preview','doc','secondary',`data-id="${r.id}"`)}${btn('PDF','pdf','download','secondary',`data-id="${r.id}"`)}${btn('Сподели','document-share','download','secondary',`data-id="${r.id}"`)}${btn('Редакция','edit','edit','secondary',`data-table="documents" data-id="${r.id}"`)}</div></div>`).join('')||empty('Няма документи от този тип.')}<div class="actions">${btn(t==='Договор'?'Нов договор':'Нова оферта','new','plus','primary',`data-table="documents" data-type="${t}"`)}</div>`}
function supplyContent(id){return `<div class="card"><h3>За следващо посещение</h3>${db.supplies.filter(r=>r.clientId===id).map(r=>`<div class="row"><label class="check grow ${r.done?'done':''}"><input type="checkbox" data-check="supplies" data-id="${r.id}" ${r.done?'checked':''}><span>${esc(r.name)} · ${esc(r.quantity)} ${esc(r.unit)}</span></label>${btn('','edit','edit','iconbtn',`data-table="supplies" data-id="${r.id}" aria-label="Редактирай консуматив"`)}</div>`).join('')||empty('Няма добавени консумативи.')}<div class="actions">${btn('Добави артикул','new','plus','secondary',`data-table="supplies" data-client="${id}"`)}${btn('В покупки','supplies-to-cart','cart','primary',`data-id="${id}"`)}</div></div>`}
function suppliesView(){return `${clientSelect('supply-client',state.supplyClient)}${state.supplyClient?supplyContent(state.supplyClient):empty('Избери клиент за списъка за следващо посещение.')}`}
function genericView(table){return `${table==='subscriptions'?period():''}<div class="card">${db[table].map(r=>recordRow(table,r)).join('')||empty()}</div>${btn('Добави '+({subscriptions:'абонамент',purchases:'покупка',equipment:'оборудване',irrigation:'поливна система',services:'услуга'}[table]),'new','plus','primary wide',`data-table="${table}"`)}`}
function recordRow(table,r){const details={subscriptions:`${cname(r.clientId)} · ${r.packageName?r.packageName+' · ':''}${r.frequency} посещения/месец · ${money(r.amount)}/месец · ${r.status}`,expenses:`${date(r.date)} · ${r.category} · ${money(r.amount)}`,purchases:`${r.quantity} ${r.unit} · ${money(r.amount)} · ${r.done?'Купено':'За купуване'}`,equipment:`${r.brand||''} ${r.model||''} · Сервиз: ${date(r.nextService)}`,irrigation:`${cname(r.clientId)} · ${r.zones||0} зони · ${r.controller||''}`,services:`${money(r.amount)} / ${r.unit||'услуга'}`};return `<button class="list-row" data-action="edit" data-table="${table}" data-id="${r.id}"><div class="avatar">${icon({subscriptions:'calendar',expenses:'money',purchases:'cart',equipment:'tool',irrigation:'water',services:'doc'}[table])}</div><div class="grow"><strong>${esc(r.name||r.title||r.description)}</strong>${table==='expenses'&&isAllocation(r)?badge('Разпределение','blue'):''}<small>${esc(details[table])}</small></div>${icon('chevron')}</button>`}
function notificationsView(){const overdue=db.visits.filter(v=>v.status==='Планирано'&&v.date<today()),upcoming=db.visits.filter(v=>v.status==='Планирано'&&v.date>=today()).sort(sortDate),maintenance=db.equipment.filter(r=>machineDue(r).due),unpaid=db.visits.filter(v=>v.status==='Изпълнено'&&due(v)>0);return `<div class="notice">Задачите се показват при отваряне на приложението. Не се изпращат системни push известия.</div><div class="card"><h3>Просрочени посещения · ${overdue.length}</h3>${overdue.map(visitRow).join('')||empty()}</div><div class="card"><h3>Предстоящи посещения · ${upcoming.length}</h3>${upcoming.map(visitRow).join('')||empty()}</div><div class="card"><h3>Неплатени посещения</h3>${unpaid.map(visitRow).join('')||empty()}</div><div class="card"><h3>Оборудване за сервиз</h3>${maintenance.map(r=>recordRow('equipment',r)).join('')||empty()}</div>`}
function settingsView(){return `<div class="card"><h2>${esc(db.settings.company)}</h2><p>${esc(db.settings.owner)}<br>${esc(db.settings.phone)}<br>${esc(db.settings.email)}</p>${btn('Фирмени данни и лого','company','edit','secondary wide')}</div><div class="card"><h3>Инсталиране и офлайн</h3><p id="install-state">${matchMedia('(display-mode: standalone)').matches?'Приложението работи в самостоятелен режим.':'Отвори публикувания HTTPS адрес в Chrome за Android → меню ⋮ → „Инсталиране на приложението“ или „Добавяне към началния екран“.'}</p>${btn('Инсталирай','install','download','primary wide')}<p class="muted" style="margin-top:12px">${swReady?'Файловете са кеширани за офлайн работа.':'За офлайн работа е нужно първо зареждане през HTTPS или localhost.'}</p>${btn('Провери за обновление','update','download','secondary wide')}${btn('Защита на локалните данни','persist','box','secondary wide')}</div><div class="card"><h3>Архивиране и възстановяване</h3><p>Архивът включва всички записи, настройки и снимки. Пази копие извън телефона. Изчистване на данните на сайта може да изтрие локалната база.</p>${btn('Изтегли JSON архив','backup','download','primary wide')}<label class="field" style="margin-top:14px">Възстанови от JSON<input type="file" id="restore-file" accept=".json,application/json"></label>${corrupt?btn('Нечетимите данни — износ','rawbackup','download','danger wide'):''}<p class="muted">Възстановяването заменя текущите данни след потвърждение. Автоматично се изтегля архив на текущото състояние.</p></div><div class="card"><h3>Инструменти</h3><div class="actions">${btn('Проценти','allocation','chart','secondary')}${btn('Ценоразпис','go','doc','secondary','data-page="services"')}</div>${btn('Зареди примерни данни','demo','leaf','secondary wide')}<p class="muted">Примерите са отделни тестови записи, не действителни приходи на GreenForce.</p>${btn('Изтрий всички данни','reset','trash','danger wide')}</div>`}
