function fieldHTML(field,value){let {key,label,type,required,options,full}=field,attr=`name="${key}" id="field-${key}" ${required?'required':''}`,v=esc(value??'');let input;
 if(type==='textarea')input=`<textarea ${attr} maxlength="15000" ${key==='items'?'placeholder="Косене | 2 | 65"':''}>${v}</textarea>`;
 else if(type==='visit')input=`<select ${attr}>${visitSelectOptions(value,'')}</select>`;
 else if(type==='system')input=`<select ${attr}><option value="">Избери система…</option>${db.irrigation.map(s=>`<option value="${esc(s.id)}" ${s.id===value?'selected':''}>${esc(cname(s.clientId))} · ${esc(s.name)}</option>`).join('')}</select>`;
 else if(type==='select'||type==='client'||type==='subscription'){const opts=type==='client'?db.clients.map(c=>[c.id,c.name]):type==='subscription'?db.subscriptions.map(s=>[s.id,cname(s.clientId)+' · '+s.name]):options.map(x=>[x,x]);input=`<select ${attr}><option value="">Избери…</option>${opts.map(([id,n])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(n)}</option>`).join('')}</select>`;}
 else if(type==='file')input=`<input ${attr} type="file" accept="image/*">${value?'<small>Има запазена снимка. Изборът на нова я заменя.</small><label><input type="checkbox" name="removePhoto"> Премахни снимката</label>':''}`;
 else if(type==='checkbox')input=`<input ${attr} type="checkbox" ${value?'checked':''}>`;
 else input=`<input ${attr} type="${['integer','percent'].includes(type)?'number':type}" value="${v}" ${['number','integer','percent'].includes(type)?`min="0" max="${type==='percent'?100:100000000}" step="${key==='durationHours'?'any':type==='integer'?1:.01}"`:''} ${type==='text'?'maxlength="500"':''}>`;
 return `<label class="field ${full?'full':''}" for="field-${key}">${esc(label)}${input}${key==='extraServices'?`<small>${esc(GFTemplates.architectNote)}</small>`:''}</label>`;}
