 if(table==='documents'){const year=Number(today().slice(0,4))+(Number(today().slice(5,7))>9?1:0);r.template=r.template||(existing?GFTemplates.names[0]:r.type==='Договор'?GFTemplates.names[2]:GFTemplates.names[1]);r.periodStart=r.periodStart||year+'-03-01';r.periodEnd=r.periodEnd||year+'-11-30';r.visitsPerMonth=r.visitsPerMonth||2;r.paymentDays=r.paymentDays||7;r.scope=r.scope||(existing&&!r.pricingMode&&GFTemplates.enabled(r)?GFTemplates.scope:'');if(!existing){r.priceBasis=r.priceBasis||(r.type==='Договор'||pref.items?'month':'once');r.conditions='';r.firstMonthApproval=true;r.includePriceProtocol=false;r.extraServices=GFTemplates.rates;r.validUntil=new Date(Date.now()+30*86400000).toISOString().slice(0,10)}}
