function errorForm(message){let e=$('#form-error');if(e){e.textContent=message;e.hidden=false}else toast(message)}
async function compressImage(file,max=700,quality=.8){if(file.size>12000000)throw Error('Снимката трябва да е под 12 MB');const bmp=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,max/bmp.width,max/bmp.height);canvas.width=bmp.width*scale;canvas.height=bmp.height*scale;canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close();return canvas.toDataURL('image/jpeg',quality);}
async function submitRecord(form){const table=form.dataset.table,id=form.dataset.id,old=db[table].find(r=>r.id===id),fd=new FormData(form),r={...old,id:id||uid()};try{for(const f of schemas[table]){const x=fd.get(f.key);if(f.type==='file'){if(fd.get('removePhoto'))r[f.key]='';if(x?.size)r[f.key]=await compressImage(x);continue}if(f.type==='checkbox'){r[f.key]=fd.has(f.key);continue}if(['number','integer','percent'].includes(f.type)){r[f.key]=x===''?0:Number(x);if(!Number.isFinite(r[f.key])||r[f.key]<0||r[f.key]>100000000)throw Error('Невалидна числова стойност');if(f.type==='percent'&&r[f.key]>100)throw Error('Отстъпката трябва да е от 0 до 100%');}else r[f.key]=String(x||'').trim();if(f.required&&r[f.key]===''&&!(table==='documents'&&f.key==='items'&&form.querySelector('#quote-mode')?.value!=='lines'))throw Error('Попълни: '+f.label);}
 if(table==='irrigation'){r.zoneConfigs=collectZones(r.zones);collectIrrigationBuild(form,r);validateIrrigationRecord(r);}if(table==='irrigationLogs')validateIrrigationLog({...r,expenseId:undefined},db);if(table==='visits'){if(r.durationHours>168)throw Error('Продължителността на едно посещение трябва да е до 168 часа.');delete r.duration;}
 if(['expenses','purchases'].includes(table))prepareExpenseLink(r);if(table==='visits'&&old&&r.clientId!==old.clientId&&[...db.expenses,...db.purchases].some(e=>e.visitId===id))throw Error('Посещението има свързани разходи. Първо ги прехвърли към правилния обект.');
 if(table==='portfolio')validatePortfolio({portfolio:[r]});
 if(r.clientId&&!client(r.clientId))throw Error('Избери съществуващ клиент');
 if(table==='visits'&&r.subscriptionId&&db.subscriptions.find(s=>s.id===r.subscriptionId)?.clientId!==r.clientId)throw Error('Абонаментът е за друг клиент.');
 if(table==='visits'&&directPaid(r)>net(r)+.005)throw Error('Цената не може да е под вече платената сума. Първо коригирай плащанията във Финанси.');
 if(table==='visits'&&r.status==='Отменено'&&paid(r)>0)throw Error('Посещението има плащания. Първо коригирай плащанията.');
 if(table==='subscriptions'&&(r.end<r.start||r.frequency<1||r.frequency>31))throw Error('Провери срока и броя посещения (1–31).');
 if(table==='documents'){collectDocumentPricing(form,r);collectDocumentExtras(form,r);collectPortfolioDocument(form,r);collectIrrigationDocument(form,r);if(old&&r.type!==old.type)throw Error('За друг вид документ създай нов запис.');r.number=old?old.number:nextDocNumber(r.type,r.date);if(GFTemplates.enabled(r)&&(!r.periodStart||!r.periodEnd||r.periodEnd<r.periodStart||r.visitsPerMonth<1||r.visitsPerMonth>31||r.paymentDays<1||!documentScope(r)))throw Error('Попълни срок, брой посещения (1–31), дни за плащане и включени дейности.');r.clientSnapshot={...client(r.clientId)};r.companySnapshot={...db.settings};if(r.validUntil<r.date)throw Error('Крайната дата е преди издаването.');if(db.documents.some(d=>d.id!==id&&d.type===r.type&&d.number===r.number))throw Error('Вече има документ с този номер.');const lines=docLines(r);if(!lines.length||lines.some(l=>!l.name||!Number.isFinite(l.qty)||l.qty<=0||!Number.isFinite(l.price)||l.price<0||l.price>100000000||l.qty>1000000))throw Error('Всеки ред трябва да е: описание | положително количество | цена.');}
 if(table==='purchases'&&old?.expenseId&&!db.expenses.some(e=>e.id===old.expenseId))throw Error('Свързаният разход не е намерен.');
 const refs=await commitRecommendations(table,r,old,form);let photos;try{photos=await commitPhotos(table,r,old)}catch(e){await MediaStore.remove(refs.created).catch(()=>{});throw e}photos.created.push(...refs.created);photos.obsolete.push(...refs.obsolete);
 if(change(()=>{if(table==='documents')retainDocNumber(r);syncPostedExpense(table,r);const i=db[table].findIndex(x=>x.id===r.id);if(i<0)db[table].push(r);else db[table][i]=r;})){closeDialog();toast('Записът е запазен.');render();await MediaStore.remove(photos.obsolete.filter(id=>!mediaRecords(db).some(r=>mediaRefs(r).includes(id)))).catch(()=>{});}else await MediaStore.remove(photos.created).catch(()=>{});
 }catch(e){errorForm(e.message)}}
async function confirmAction(title,text,fn,danger=false){modal(title,`<p>${esc(text)}</p><div class="actions">${btn('Отказ','close','close','secondary')}<button class="${danger?'danger':'primary'}" id="confirm-yes">${icon('check')}Потвърди</button></div>`);$('#confirm-yes').onclick=async()=>{try{const result=await fn();if(result!==false){closeDialog();render()}}catch(e){toast(e.message)}};}
function removeRecord(table,id){if(table==='recommendations'&&db.documents.some(d=>(d.recommendationIds||[]).includes(id)))return toast('Препоръката е избрана в документ. Първо я премахни от неговите приложения.');const guard=managerBeforeDelete(table,id);if(guard)return toast(guard);if(table==='clients'&&TABLES.some(k=>k!=='clients'&&db[k].some(r=>r.clientId===id)))return toast('Клиентът има свързани записи. Първо ги премахни или прехвърли.');if(table==='irrigation'&&db.irrigationLogs.some(l=>l.systemId===id))return toast('Системата има дневник. Запази историята или премахни свързаните записи първо.');if(table==='visits'&&db.irrigationLogs.some(l=>l.visitId===id))return toast('Посещението е свързано с дневник на поливна система. Първо премахни връзката.');if(table==='visits'&&[...db.expenses,...db.purchases].some(e=>e.visitId===id))return toast('Посещението има разходи или покупки. Първо премахни връзката им към него.');if(table==='visits'&&db.payments.some(p=>p.visitId===id))return toast('Посещението има плащания. Първо ги премахни от Финанси.');const record=db[table].find(r=>r.id===id),photos=mediaRefs(record);confirmAction('Изтриване на запис','Да изтрия ли избрания запис? Това действие не може да се отмени.',async()=>{const ok=change(()=>{if(table==='documents')retainDocNumber(record);db[table]=db[table].filter(r=>r.id!==id);if(table==='expenses')db.irrigationLogs.forEach(l=>{if(l.expenseId===id)delete l.expenseId});if(table==='expenses')db.purchases.forEach(p=>{if(p.expenseId===id)delete p.expenseId});});if(ok)await MediaStore.remove(photos.filter(id=>!mediaRecords(db).some(r=>mediaRefs(r).includes(id)))).catch(()=>{});return ok;},true);}
function payment(id){const v=db.visits.find(r=>r.id===id);modal('Плащане по посещение',`<p>${esc(cname(v.clientId))} · ${esc(v.service)}<br>Остатък: <strong>${money(due(v))}</strong></p><form id="payment-form" data-id="${id}"><div class="form-grid">${[f('date','Дата на получаване на плащането','date',true),f('amount','Сума €','number',true),f('method','Начин','select',true,['В брой','По банка','С карта']),f('notes','Бележка')].map(x=>fieldHTML(x,{date:v.date,amount:due(v),method:'В брой'}[x.key])).join('')}</div><div id="form-error" class="error" hidden></div><button class="primary wide" style="margin-top:14px" type="submit">Запиши плащане</button></form>`);}
function documentText(r){if(r.irrigationQuote)return irrigationQuoteText(r);if(GFTemplates.enabled(r))return GFTemplates.plain(r);const c=client(r.clientId)||{},s=db.settings;return `${documentContractorText(r)}\n\n${r.type.toUpperCase()} № ${r.number}\n${r.title}\n${r.packageName?'Абонаментен пакет: '+r.packageName+'\n':''}Дата: ${date(r.date)} · Валидност / край: ${date(r.validUntil)}\nСтатус: ${r.status}\n\nВЪЗЛОЖИТЕЛ: ${c.name||''}\nЛице за контакт: ${c.contact||''}\nАдрес на обекта: ${c.address||''}\nТелефон: ${c.phone||''} · Имейл: ${c.email||''}\n\nВКЛЮЧЕНИ ДЕЙНОСТИ\n${documentScope(r)||r.title}${documentBonusText(r)?'\n\n'+documentBonusText(r):''}\n\nПОЗИЦИИ (EUR)\n${docLines(r).map((l,i)=>`${i+1}. ${l.name}\n   ${l.qty} × ${money(l.price)} = ${money(l.qty*l.price)}`).join('\n')}\n\nМеждинна сума: ${money(documentSubtotal(r))}\nОтстъпка: ${r.discount||0}%\nЦена ${documentPriceLabel(r)}\nОБЩО: ${money(docTotal(r))}\nПосочената сума е крайна по този документ.\n\nУСЛОВИЯ\n${r.conditions||''}\n\n${r.notes||''}${documentExtraServicesText(r)}\n\nЗа възложителя: __________________\nЗа изпълнителя: ${r.contractorMode?documentContractorSignature(r)+'\n':''}__________________\nДата на подписване: ______________`}
function visitText(v){return `${db.settings.company}\nПРОТОКОЛ ЗА ПОСЕЩЕНИЕ\n\nКлиент: ${cname(v.clientId)}\nОбект: ${client(v.clientId)?.address||''}\nДата: ${date(v.date)} · Час: ${v.time}\nПродължителност: ${visitHours(v).toLocaleString('bg-BG')} часа\nСтатус: ${v.status}\n\nУслуги:\n${v.service}\n\nБазова цена: ${money(v.amount)}\nОтстъпка: ${v.discount||0}%\nКрайна стойност: ${money(net(v))}\nПлатено: ${money(paid(v))}\nОстатък: ${money(due(v))}\n\n${v.notes||''}${visitExpenseReportText(v,true)}\n\nПриел: ____________________\nИзпълнил: ____________________`}
function clientText(id){const c=client(id),vs=db.visits.filter(v=>v.clientId===id).sort(sortDate);return `КЛИЕНТСКО ДОСИЕ\n${c.name}\n${completedVisitText(id)}\n${c.address}\n${c.phone} · ${c.email}\n${c.type} · ${c.area||'—'} m²\n\nБележки: ${c.notes||''}\n\nИСТОРИЯ\n${vs.map(v=>`${date(v.date)} ${v.time} · ${v.status}\n${v.service}\nСума: ${money(net(v))} · Платено: ${money(paid(v))}`).join('\n\n')}\n\nПолучено общо: ${money(sum(cashEntries().filter(p=>cashClient(p)===id),p=>p.amount))}${clientExpenseDossierText(id)}\n\nПОЛИВНИ СИСТЕМИ\n${db.irrigation.filter(r=>r.clientId===id).map(r=>`${r.name}\n${r.controller} · ${r.zones} зони\n${r.pump}\nДебит ${r.flow} l/min · Налягане ${r.pressure} bar\n${r.zoneDetails||''}\n${r.notes||''}`).join('\n\n')}${clientIrrigationJournalText(id)}`}
function reportText(){const s=stats();return `МЕСЕЧЕН ОТЧЕТ ${state.month}\n\nПолучени приходи: ${money(s.income)}\nПлатени разходи: ${money(s.expense)}\nПаричен резултат: ${money(s.income-s.expense)}\nРазпределени средства: ${money(s.allocated)}\nСвободен остатък: ${money(s.income-s.expense-s.allocated)}\n\nПЛАЩАНИЯ\n${cashEntries().filter(paymentInMonth).map(p=>`${date(p.date)} · ${cname(cashClient(p))} · ${money(p.amount)} · ${p.method}`).join('\n')}\n\nРАЗХОДИ\n${db.expenses.filter(inMonth).map(e=>`${date(e.date)} · ${e.description} · ${isAllocation(e)?'Разпределение: ':''}${e.category} · ${money(e.amount)}`).join('\n')}\n\nОснова на приходите: ${reportBasis()==='visit'?'дата на посещението (само получени суми)':'дата на плащането'}. Разходи: дата на разхода.`}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;(document.querySelector('dialog[open]')||document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function exportPDF(title,text,name,options={}){try{toast('Подготвям PDF…');download(await createPDF(title,text,options),name+'.pdf');toast('PDF файлът е създаден.')}catch(e){toast('PDF не е създаден: '+e.message)}}
async function backup(){return managerBackup();}
function csvExport(){const quote=x=>'"'+String(x??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"',rows=[['Вид','Дата на отчитане','Клиент','Описание','Категория','Сума EUR'],...cashEntries().filter(paymentInMonth).map(p=>['Приход',paymentDate(p,reportBasis()),cname(cashClient(p)),p.notes,p.method,p.amount]),...db.expenses.filter(inMonth).map(e=>[isAllocation(e)?'Разпределение':'Разход',e.date,cname(e.clientId),e.description,e.category,e.amount])];download(new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'GreenForce-'+state.month+'.csv')}
function icsExport(){const e=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&'),stamp=new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//GreenForce//Manager Pro//BG','CALSCALE:GREGORIAN'];for(const v of db.visits.filter(v=>inMonth(v)&&v.status!=='Отменено')){const start=new Date(v.date+'T'+(v.time||'09:00')+':00'),end=new Date(+start+Math.max(1/60,visitHours(v)||1)*3600000),fmt=d=>d.toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';lines.push('BEGIN:VEVENT','UID:'+v.id+'@greenforce.local','DTSTAMP:'+stamp,'DTSTART:'+fmt(start),'DTEND:'+fmt(end),'SUMMARY:'+e(cname(v.clientId)+' — '+v.service),'LOCATION:'+e(client(v.clientId)?.address),'DESCRIPTION:'+e(v.notes),'END:VEVENT')}lines.push('END:VCALENDAR');const enc=new TextEncoder();const folded=lines.map(line=>{let result='',col=0;for(const ch of line){const n=enc.encode(ch).length;if(col+n>73){result+='\r\n ';col=1}result+=ch;col+=n}return result}).join('\r\n')+'\r\n';download(new Blob([folded],{type:'text/calendar;charset=utf-8'}),'GreenForce-'+state.month+'.ics')}
function companyEditor(){modal('Фирмени данни и лого',`<form id="company-form"><div class="form-grid">${[f('company','Фирма / марка','text',true,null,true),f('legalName','Юридическо лице'),f('owner','Представител / основател'),f('iban','IBAN'),f('registration','ЕИК / идентификатор'),f('phone','Телефон','tel'),f('email','Имейл','email'),f('address','Адрес','text',false,null,true),f('logo','Лого','file',false,null,true)].map(f=>fieldHTML(f,db.settings[f.key])).join('')}</div><div id="form-error" class="error" hidden></div><button class="primary wide" style="margin-top:14px" type="submit">Запази</button></form>`)}
function allocationEditor(){modal('Проценти за разпределение',`<form id="allocation-form">${Object.entries(db.settings.allocation).map(([n,v],i)=>`<label class="field" style="margin:10px 0">${esc(n)} %<input required type="number" min="0" max="100" step="0.01" name="p${i}" value="${v}"></label>`).join('')}<p>Сборът трябва да е точно 100%.</p><div id="form-error" class="error" hidden></div><button class="primary wide" type="submit">Запази</button></form>`)}
function schedule(id){const s=db.subscriptions.find(r=>r.id===id);if(s.status!=='Активен')return toast('Абонаментът не е активен.');const [year,month]=state.month.split('-').map(Number),last=new Date(year,month,0).getDate();let dates=Array.from({length:s.frequency},(_,i)=>state.month+'-'+String(1+Math.floor(i*last/s.frequency)).padStart(2,'0')).filter(d=>d>=s.start&&d<=s.end&&!db.visits.some(v=>v.subscriptionId===s.id&&v.date===d));if(!dates.length)return toast('Няма нови дати в избрания месец или срокът е извън него.');confirmAction('Планиране на абонамент',`Ще добавя ${dates.length} посещения за ${state.month}. Датите са равномерно разпределени и могат да се редактират. Месечната цена се разделя на ${s.frequency} посещения.`,()=>change(()=>{const base=cents(s.amount),each=Math.floor(base/s.frequency);dates.forEach(d=>{const i=Array.from({length:s.frequency},(_,i)=>1+Math.floor(i*last/s.frequency)).indexOf(Number(d.slice(8)));db.visits.push({id:uid(),clientId:s.clientId,subscriptionId:s.id,date:d,time:'09:00',service:s.service,amount:(i===s.frequency-1?base-each*(s.frequency-1):each)/100,discount:0,status:'Планирано',durationHours:1,notes:s.notes||''})})}));}
function purchaseExpense(id){const p=db.purchases.find(r=>r.id===id);if(p.expenseId)return toast('Покупката вече има свързан разход.');if(!p.done)return toast('Първо отбележи покупката като купена и запази.');if(!(p.amount>0))return toast('Въведи действителната платена цена.');confirmAction('Отчитане на покупка',`Да добавя ли разход ${money(p.amount)} за „${p.name}“?`,()=>change(()=>{p.expenseId=uid();db.expenses.push({id:p.expenseId,description:p.name,date:p.date,amount:p.amount,category:p.category||'Консумативи',clientId:p.clientId||'',visitId:p.visitId||'',receiptPhotos:[...(p.receiptPhotos||[])],notes:'От покупка: '+(p.supplier||'')})}));}
function demo(){if(TABLES.some(t=>db[t].length))return toast('Примерите се зареждат само в празна база, за да няма смесване с твоите записи.');confirmAction('Примерни данни','Ще добавя обозначени тестови клиенти, посещения, плащания и техника. Можеш да ги изчистиш от Настройки, преди да започнеш работа.',()=>change(()=>{const m=state.month,d=m+'-05',c1=uid(),c2=uid(),v1=uid(),v2=uid();db.clients.push({id:c1,name:'ДЕМО · Коркина — Илия',contact:'Примерен клиент',type:'Къща',area:300,address:'с. Коркина',phone:'',email:'',notes:'Само тестови данни. Редактирай или изтрий преди реална употреба.'},{id:c2,name:'ДЕМО · София — Кооперация',type:'Жилищна сграда',area:800,address:'кв. Изток, София',phone:'',notes:'Тестов запис'});db.visits.push({id:v1,clientId:c1,date:d,time:'09:00',service:'Косене и оформяне',amount:65,discount:0,status:'Изпълнено',durationHours:1.5,notes:'Примерен протокол'},{id:v2,clientId:c2,date:m+'-20',time:'11:00',service:'Абонаментна поддръжка',amount:160,discount:0,status:'Планирано',durationHours:2,notes:''});db.payments.push({id:uid(),visitId:v1,date:d,amount:65,method:'В брой',notes:'ДЕМО'});db.expenses.push({id:uid(),description:'ДЕМО · Гориво',date:d,amount:22,category:'Гориво',clientId:c1,notes:''});db.subscriptions.push({id:uid(),clientId:c2,name:'ДЕМО · Поддръжка',amount:320,frequency:2,start:m+'-01',end:m+'-28',status:'Активен',service:'Косене, почистване, оформяне',notes:''});db.documents.push({id:uid(),type:'Оферта',number:'DEMO-001',title:'Абонаментна поддръжка',clientId:c2,date:m+'-01',validUntil:m+'-28',status:'Чернова',discount:0,items:'Месечна поддръжка | 1 | 320',conditions:'Две посещения месечно. Материалите се договарят отделно.',notes:'Примерна оферта'});db.supplies.push({id:uid(),clientId:c1,name:'Тримерна корда',quantity:1,unit:'ролка',done:false,notes:''});db.equipment.push({id:uid(),name:'ДЕМО · Косачка',brand:'Husqvarna',model:'LC151S',date:today(),amount:0,nextService:today(),notes:'Попълни реалните сервизни данни.'});db.irrigation.push({id:uid(),name:'ДЕМО · Поливна система',clientId:c1,zones:6,controller:'6-зонов контролер',pump:'Сондажна',flow:0,pressure:0,zoneDetails:'Въведи проверените технически данни по зони.',notes:'Примерен запис'});db.services.push({id:uid(),name:'Косене — примерна цена',amount:65,unit:'посещение',notes:'Редактируема цена; не е пазарна оценка.'});}));}
