loadSavedData();
let installPrompt=null,swReady=false,registration=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Приложението е инсталирано.')});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('storage',e=>{if(e.key===KEY){try{db=e.newValue?validate(JSON.parse(e.newValue)):blank();render();toast('Данните са обновени от друг отворен прозорец.')}catch(err){toast('Неуспешно обновяване от друг прозорец.')}}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,t=el.dataset.table;try{switch(a){case'back':if(navIndex>0)history.back();else go('home');break;case'go':go(el.dataset.page);break;case'annualpdf':await exportPDF('Годишен отчет '+state.month.slice(0,4),annualText(),'GreenForce-year-'+state.month.slice(0,4));break;case'subscription-doc':subscriptionDocument(id,el.dataset.type);break;case'photo-close':closeDialog('photo-viewer');break;case'photo-remove':photoDraft.groups[el.dataset.group].splice(Number(el.dataset.index),1);paintPhotoDraft();break;case'photo-preview':{const p=photoDraft.groups[el.dataset.group][Number(el.dataset.index)];await viewPhoto(p.data||await MediaStore.get(p.id));break}case'photo-stored':await viewPhoto(await MediaStore.get(el.dataset.photoId));break;case'close':closeDialog();break;case'tab':navPush();state.tab=el.dataset.value;render();break;case'month':{navPush();const [y,m]=state.month.split('-').map(Number),d=new Date(y,m-1+Number(el.dataset.dir),1);state.month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;state.day=state.month+'-01';render();break}case'day':navPush();state.day=el.dataset.date;render();break;case'client':go('client',{client:id});break;case'new':if(schemas[t].some(f=>f.key==='clientId'&&f.required)&&!db.clients.length)return toast('Първо добави клиент.');editor(t,'',{...(el.dataset.client?{clientId:el.dataset.client}:{}),...(el.dataset.type?{type:el.dataset.type}:{})});break;case'edit':editor(t,id);break;case'delete':removeRecord(t,id);break;case'pay':payment(id);break;case'payment-date':{const p=db.payments.find(p=>p.id===id);modal('Дата на плащането',`<form id="payment-date-form" data-id="${p.id}">${fieldHTML(f('date','Дата на получаване на плащането','date',true),p.date)}<button type="submit" class="primary wide">Запази датата</button></form>`);break}case'delpayment':confirmAction('Изтриване на плащане','Да премахна ли това плащане? Остатъкът по посещението ще се преизчисли.',()=>change(()=>{db.payments=db.payments.filter(p=>p.id!==id)}),true);break;case'preview':await previewDocument(db.documents.find(r=>r.id===id));break;case'pdf':{const r=db.documents.find(r=>r.id===id);await exportDocumentPDF(r);break}case'visitpdf':{const v=db.visits.find(r=>r.id===id);await exportPDF('Посещение '+date(v.date),visitText(v),'GreenForce-visit-'+v.date,await visitPDFOptions(v,'Протокол за посещение'));break}case'clientpdf':await exportPDF('Клиентско досие',clientText(id),'GreenForce-client-'+today());break;case'reportpdf':await exportPDF('Отчет '+state.month,reportText(),'GreenForce-report-'+state.month);break;case'csv':csvExport();break;case'ics':icsExport();break;case'backup':await backup();break;case'rawbackup':download(new Blob([localStorage.getItem(KEY)||''],{type:'application/json'}),'GreenForce-recovery-raw.json');break;case'company':companyEditor();break;case'new-allocation':editor('expenses','',{flowType:'Разпределение на остатъка',category:allocationCategories()[0],description:'Разпределение на средства'});break;case'allocation':allocationEditor();break;case'schedule':schedule(id);break;case'purchase-expense':purchaseExpense(id);break;case'supplies-to-cart':{let items=db.supplies.filter(r=>r.clientId===id&&!r.done&&!db.purchases.some(p=>p.sourceSupplyId===r.id&&!p.done));if(!items.length)return toast('Няма нови неприготвени артикули за добавяне.');if(change(()=>items.forEach(r=>db.purchases.push({id:uid(),sourceSupplyId:r.id,clientId:r.clientId,name:r.name,quantity:r.quantity,unit:r.unit,amount:0,date:today(),category:'Консумативи',supplier:'',done:false,receiptPhotos:[...(r.receiptPhotos||[])],notes:r.notes||''}))))toast('Добавени в Пазаруване: '+items.length);break}case'demo':demo();break;case'reset':modal('Изтриване на всички данни',`<p>Изтегли архив, преди да продължиш. Напиши <strong>ИЗТРИЙ</strong>, за да потвърдиш.</p><input class="search" id="reset-word" aria-label="Потвърждение за изтриване">${btn('Изтегли архив','backup','download','secondary wide')}<button class="danger wide" id="reset-confirm" style="margin-top:10px">Изтрий завинаги</button>`);$('#reset-confirm').onclick=async()=>{if($('#reset-word').value!=='ИЗТРИЙ')return toast('Напиши ИЗТРИЙ за потвърждение.');try{localStorage.removeItem(KEY);await MediaStore.clear().catch(()=>{});db=blank();corrupt=false;storageError='';closeDialog();go('home');toast('Данните са изтрити.')}catch(e){toast(e.message)}};break;case'install':if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else toast(matchMedia('(display-mode: standalone)').matches?'Приложението вече е отворено самостоятелно.':'В Chrome отвори меню ⋮ → Инсталиране / Добавяне към началния екран. Нужен е публикуван HTTPS адрес.');break;case'persist':{const ok=await navigator.storage?.persist?.();toast(ok?'Браузърът разреши постоянно съхранение. Пази и външен архив.':'Браузърът не предостави гаранция за постоянно съхранение. Пази външен архив.');break}case'update':if(registration){await registration.update();if(registration.waiting)confirmAction('Нова версия','Презареждането ще активира новите файлове. Записаните данни се запазват.',()=>{registration.waiting.postMessage('SKIP_WAITING');return true});else toast('Няма открита нова версия.')}else toast('Service Worker не е активен. Отвори HTTPS адреса.');break;}}catch(err){toast('Действието не е изпълнено: '+err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='client-search'){state.filter=e.target.value;$('#client-list').innerHTML=clientList()}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='report-basis'){navPush();state.reportBasis=el.value;render();return}try{if(el.name==='zones'&&zoneDraft){resizeZones(el.value);return}if(el.dataset.headCount!==undefined){resizeHeads(Number(el.dataset.headCount),el.value);return}if(el.name==='packageName'){applyPackage(el.value);return}if(['type','date','template'].includes(el.name))refreshDocNumber();if(el.dataset.photoUpload||el.dataset.photoCamera){await addPhotoFiles(el);return}if(el.name==='template'){const type=$('#field-type');if(el.value.includes('договор'))type.value='Договор';else if(el.value.includes('Оферта'))type.value='Оферта';if(el.value===GFTemplates.names[3]){const start=$('#field-periodStart').value;if(start){const d=new Date(start+'T12:00:00');d.setFullYear(d.getFullYear()+1);d.setDate(d.getDate()-1);$('#field-periodEnd').value=d.toISOString().slice(0,10)}$('#field-firstMonthApproval').checked=false}refreshDocNumber();if(el.value!==GFTemplates.names[0]&&!$('#field-scope').value)$('#field-scope').value=GFTemplates.scope;}if(el.name==='flowType'){const category=$('#field-category');category.innerHTML='<option value="">Избери…</option>'+(el.value==='Разпределение на остатъка'?allocationCategories():cats).map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}if(el.id==='month'&&el.value){navPush();state.month=el.value;state.day=state.month+'-01';render()}if(el.id==='visit-client'){navPush();state.filter=el.value;render()}if(el.id==='supply-client'){navPush();state.supplyClient=el.value;render()}if(el.dataset.check==='supplies'){if(change(()=>{db.supplies.find(r=>r.id===el.dataset.id).done=el.checked}))render();else el.checked=!el.checked}if(el.id==='catalog-pick'&&el.value){const r=db.services.find(r=>r.id===el.value),amount=$('#field-amount'),service=$('#field-service');service.value=(service.value?service.value+'\n':'')+r.name;amount.value=(cents(amount.value)+cents(r.amount))/100;}
 if(el.id==='restore-file'&&el.files[0]){const file=el.files[0];el.value='';if(file.size>300000000)throw Error('Архивът трябва да е под 300 MB');const incoming=validate(JSON.parse(await file.text()));checkArchiveMedia(incoming);confirmAction('Възстановяване на архив',`Архивът съдържа ${incoming.clients.length} клиенти, ${incoming.visits.length} посещения и ${incoming.payments.length} плащания. Ще замени всички текущи данни.`,async()=>{if(!corrupt)await backup();const old=db,wasCorrupt=corrupt;try{await prepareRestoredMedia(incoming);corrupt=false;db=incoming;save();storageError='';navRevision++;toast('Архивът е възстановен.');return true}catch(err){db=old;corrupt=wasCorrupt;toast('Архивът не е възстановен: '+err.message);return false}});}
 }catch(err){toast('Неуспешно действие: '+err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]');if(button?.disabled)return;if(button)button.disabled=true;try{if(form.id==='payment-date-form'){const date=String(new FormData(form).get('date'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Невалидна дата');if(change(()=>{db.payments.find(p=>p.id===form.dataset.id).date=date})){closeDialog();render()}}if(form.id==='record-form')await submitRecord(form);if(form.id==='payment-form'){const v=db.visits.find(v=>v.id===form.dataset.id),fd=new FormData(form),amount=Number(fd.get('amount'));if(!Number.isFinite(amount)||amount<=0||cents(amount)>cents(due(v)))return errorForm('Сумата трябва да е положителна и до неплатения остатък.');if(change(()=>db.payments.push({id:uid(),visitId:v.id,amount:cents(amount)/100,date:String(fd.get('date')),method:String(fd.get('method')),notes:String(fd.get('notes')||'')}))){closeDialog();toast('Плащането е записано.');render()}}
 if(form.id==='company-form'){const fd=new FormData(form),s={...db.settings};for(const n of ['company','legalName','owner','iban','registration','phone','email','address'])s[n]=String(fd.get(n)||'').trim();if(fd.get('removePhoto'))s.logo='';if(fd.get('logo')?.size)s.logo=await compressImage(fd.get('logo'));if(change(()=>db.settings=s)){closeDialog();render();toast('Фирмените данни са запазени.')}}
 if(form.id==='allocation-form'){const fd=new FormData(form),a=Object.fromEntries(Object.keys(db.settings.allocation).map((n,i)=>[n,Number(fd.get('p'+i))]));if(Math.abs(Object.values(a).reduce((s,v)=>s+v,0)-100)>.001)return errorForm('Сборът на процентите трябва да е 100%.');if(change(()=>db.settings.allocation=a)){closeDialog();render();toast('Процентите са записани.')}}
 }catch(err){errorForm(err.message)}finally{if(button)button.disabled=false}});
setupManager();setupFlora();setupQuotes();setupRecommendations();setupDocumentExtras();setupExpenseJournal();setupPortfolio();setupIrrigationPlanner();DriveBackup.setup();render();setupNavigation();
if('serviceWorker'in navigator){const hadController=!!navigator.serviceWorker.controller;navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async r=>{registration=r;await navigator.serviceWorker.ready;swReady=true;const el=$('#offline-status');if(el)el.textContent='Готово за офлайн';r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Има обновление. Активирай го от Настройки.')})});}).catch(()=>{const el=$('#offline-status');if(el)el.textContent='Офлайн кешът не е активен';});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&registration?.active&&navigator.serviceWorker.controller&&!reloading&&swReady){reloading=true;location.reload()}})}

function documentPDFOptions(r){if(r.irrigationQuote)return irrigationQuotePDFOptions(r);const company=GFTemplates.company(r),c=GFTemplates.customer(r),coverImage=r.coverPhoto||'./assets/document-cover.jpeg';return {cover:{image:coverImage,title:r.priceBasis&&documentBasis(r)!=='month'?r.type+' за градинарски услуги':r.type==='Оферта'?'Оферта за поддръжка':'Договор за поддръжка',price:money(docTotal(r)),priceLabel:documentPriceLabel(r),owner:r.contractorMode==='brand'?company.company:company.owner,facts:[['Обект',[c.name,c.address].filter(Boolean).join('\n')||cname(r.clientId)],['Период',r.periodStart&&r.periodEnd?date(r.periodStart)+' - '+date(r.periodEnd):'До '+date(r.validUntil)],...(r.packageName?[['Пакет',r.packageName]]:[]),['Документ',r.type+' № '+r.number]]},company,blocks:GFTemplates.enabled(r)?GFTemplates.blocks(r):null}}
async function exportDocumentPDF(r,share=false){const attachments=await recommendationAttachments(r),base=await createPDF(r.type+' '+r.number,documentText(r),{...documentPDFOptions(r),photos:[...await recordImages(r),...await portfolioDocumentPhotos(r)]}),blob=await appendRecommendationPDF(base,attachments,GFTemplates.company(r)),name='GreenForce-'+r.number.replace(/[^\w\u0400-\u04ff-]/g,'_')+'.pdf';if(share)await shareReady(blob,name,'Сподели '+r.type.toLocaleLowerCase('bg'));else{download(blob,name);toast('PDF документът е готов.')}}
async function previewDocument(r){const c=GFTemplates.customer(r);modal('Преглед на документ',`<div class="cover-preview"><img src="${esc(r.coverPhoto||'./assets/document-cover.jpeg')}" alt="GreenForce"><div><strong>${esc(r.type)} № ${esc(r.number)}</strong><p>${esc(c.name||cname(r.clientId))}</p><strong>${money(docTotal(r))}${' '+esc(documentPriceLabel(r))}</strong></div></div><div class="document-preview">${esc(documentText(r))}</div>${r.documentPhotos?.length?`<h3>Снимки към документа</h3><div class="photo-grid">${r.documentPhotos.map((id,i)=>`<button type="button" class="photo-tile" data-action="photo-stored" data-photo-id="${esc(id)}" aria-label="Снимка ${i+1}"><img data-media-id="${esc(id)}" alt="Снимка ${i+1}"></button>`).join('')}</div>`:''}${r.includeRecommendations?`<h3>Препоръки към документа</h3>${(r.recommendationIds||[]).map(id=>{const ref=db.recommendations.find(x=>x.id===id);return `<p><strong>${esc(ref?.title||'Липсва препоръка')}</strong>${r.recommendationContext?'<br>'+esc(ref?.description||''):''}</p>`}).join('')}`:''}${r.includePortfolio?`<h3>Портфолио към PDF</h3>${(r.portfolioSnapshots||[]).map(p=>`<p><strong>${esc(p.location)}</strong><br>${p.beforePhotos.length} преди · ${p.afterPhotos.length} след</p>`).join('')}`:''}${btn('Изтегли PDF','pdf','download','primary wide',`data-id="${r.id}"`)}${btn('Сподели PDF','document-share','download','secondary wide',`data-id="${r.id}"`)}`);await hydratePhotos($('#modal'))}
